#!/usr/bin/env node
/**
 * build-content-kit-bundle.mjs
 *
 * Reads content-kit/{templates,sources,assets,BACKLOG.md,BRAND.md} and emits
 * functions/scheduler/lib/content-kit/_bundled.js — a single JS file the
 * Cloudflare Worker imports at build time.
 *
 * The Worker can't read the filesystem at runtime (Workers have no fs), and
 * fetching content-kit assets over HTTP would add latency + a deploy race.
 * Bundling them as JS string exports is the simplest, lowest-risk path.
 *
 * Run automatically via `npm run build:content-kit` (and `prebuild` /
 * `predeploy` hooks). Safe to run by hand any time content-kit/ changes.
 */

import { readFileSync, readdirSync, writeFileSync, mkdirSync, existsSync } from 'node:fs';
import { join, basename } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = fileURLToPath(new URL('.', import.meta.url));
const ROOT = join(__dirname, '..');
const KIT = join(ROOT, 'content-kit');
const OUT_DIR = join(ROOT, 'functions/scheduler/lib/content-kit');
const OUT = join(OUT_DIR, '_bundled.js');

function read(path) {
    return readFileSync(path, 'utf8');
}

function readBin(path) {
    return readFileSync(path);
}

/**
 * Escape a string so it survives interpolation inside a JS template literal.
 * Order matters: backslashes first, then backticks, then ${ sequences.
 */
function escapeForBacktick(str) {
    return str
        .replace(/\\/g, '\\\\')
        .replace(/`/g, '\\`')
        .replace(/\$\{/g, '\\${');
}

function readAllInDir(dir, ext) {
    const out = {};
    if (!existsSync(dir)) return out;
    for (const file of readdirSync(dir)) {
        if (!file.endsWith(ext)) continue;
        const name = basename(file, ext);
        out[name] = read(join(dir, file));
    }
    return out;
}

// --- Read inputs ---

const templates = readAllInDir(join(KIT, 'templates'), '.html');
const sources = readAllInDir(join(KIT, 'sources'), '.md');
const backlog = read(join(KIT, 'BACKLOG.md'));
const brand = read(join(KIT, 'BRAND.md'));

const logoBytes = readBin(join(KIT, 'assets/logo.svg'));
const logoSvgBase64 = logoBytes.toString('base64');

const templateNames = Object.keys(templates).sort();
const sourceNames = Object.keys(sources).sort();

if (templateNames.length === 0) {
    throw new Error('[bundle] No templates found in content-kit/templates/');
}

// --- Render output ---

function emitMap(obj) {
    return Object.entries(obj)
        .map(([key, val]) => `  ${JSON.stringify(key)}: \`${escapeForBacktick(val)}\``)
        .join(',\n');
}

const output = `// AUTO-GENERATED by scripts/build-content-kit-bundle.mjs
// Generated at: ${new Date().toISOString()}
// Sources: ${sourceNames.length}, Templates: ${templateNames.length}
// Do not edit by hand. Re-run: npm run build:content-kit

export const TEMPLATES = {
${emitMap(templates)}
};

export const SOURCES = {
${emitMap(sources)}
};

export const BACKLOG = \`${escapeForBacktick(backlog)}\`;

export const BRAND = \`${escapeForBacktick(brand)}\`;

export const LOGO_SVG_BASE64 = ${JSON.stringify(logoSvgBase64)};

export const TEMPLATE_NAMES = ${JSON.stringify(templateNames)};

export const SOURCE_NAMES = ${JSON.stringify(sourceNames)};

export const BUILD_INFO = {
  generatedAt: ${JSON.stringify(new Date().toISOString())},
  templateCount: ${templateNames.length},
  sourceCount: ${sourceNames.length},
};
`;

// --- Write ---

mkdirSync(OUT_DIR, { recursive: true });
writeFileSync(OUT, output);

const sizeKB = (Buffer.byteLength(output, 'utf8') / 1024).toFixed(1);
console.log(`[bundle] Wrote ${OUT}`);
console.log(`[bundle]   size:      ${sizeKB} KB`);
console.log(`[bundle]   templates: ${templateNames.length}`);
console.log(`[bundle]   sources:   ${sourceNames.length}`);
console.log(`[bundle]   logo b64:  ${logoSvgBase64.length} chars`);

// Sanity warning if bundle is approaching Worker free-tier limit
if (Buffer.byteLength(output, 'utf8') > 700 * 1024) {
    console.warn('[bundle] WARNING: bundle is over 700 KB — approaching Worker 1 MB limit.');
}
